1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type QuoteResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResults = {
23	  results: QuoteResult[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	const addPercent = (amount: number, percent: number): number =>
40	  amount + (amount * percent) / 100;
41	
42	const itemBasePremium = (item: Item): number =>
43	  BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const BLOCK_SIZE = 3;
46	
47	const BLOCK_PREMIUM = 60;
48	
49	const sumOf = (amounts: number[]): number =>
50	  amounts.reduce((sum, amount) => sum + amount, 0);
51	
52	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
53	
54	const sumOfItemBasePremiums = (items: Item[]): number =>
55	  sumOf(items.map(itemBasePremium));
56	
57	const groupByType = (items: Item[]): Item[][] => {
58	  const types = new Set(items.map((item) => item.type));
59	
60	  return [...types].map((type) => items.filter((item) => item.type === type));
61	};
62	
63	const itemGroupBasePremium = (items: Item[]): number =>
64	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
65	
66	const policyBasePremium = (items: Item[]): number =>
67	  sumOf(groupByType(items).map(itemGroupBasePremium));
68	
69	const roundPremiumInMHPCOsFavor = (amount: number): number =>
70	  Math.ceil(amount);
71	
72	// Every test so far quotes a new customer's first contract, so this is the only
73	// policy-wide modifier the tests demand. Loyalty and follow-up land here later.
74	const applyPolicyModifiers = (basePremium: number): number =>
75	  addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
76	
77	const CURSE_SURCHARGE_PERCENT = 50;
78	
79	const itemSurcharges = (item: Item): number =>
80	  item.cursed ? (itemBasePremium(item) * CURSE_SURCHARGE_PERCENT) / 100 : 0;
81	
82	const policyItemSurcharges = (items: Item[]): number =>
83	  sumOf(items.map(itemSurcharges));
84	
85	const quotePremium = (items: Item[]): number =>
86	  roundPremiumInMHPCOsFavor(
87	    applyPolicyModifiers(policyBasePremium(items)) +
88	      policyItemSurcharges(items) +
89	      PROCESSING_FEE,
90	  );
91	
92	export const runScenario = (scenario: Scenario): ScenarioResults => ({
93	  results: scenario.steps.map((step) => ({
94	    premium: quotePremium(step.items ?? []),
95	  })),
96	});
